class Solution:
    def countTriplesBelow(self, values: List[int], cap: int) -> int:
        n, count = len(values), 0
        for i in range(n):
            for j in range(i + 1, n):
                for k in range(j + 1, n):
                    if values[i] + values[j] + values[k] < cap:
                        count += 1
        return count

