class Solution:
    def countTriplesBelow(self, values: List[int], cap: int) -> int:
        a, total = sorted(values), 0
        for i in range(len(a) - 2):
            j, k = i + 1, len(a) - 1
            while j < k:
                if a[i] + a[j] + a[k] < cap:
                    total += k - j
                    j += 1
                else:
                    k -= 1
        return total

