class Solution {
    public long countTriplesBelow(int[] values, int cap) {
        int[] a = values.clone();
        Arrays.sort(a);
        long total = 0;
        for (int i = 0; i + 2 < a.length; i++) {
            int j = i + 1, k = a.length - 1;
            while (j < k) {
                if (a[i] + a[j] + a[k] < cap) { total += k - j; j++; }
                else k--;
            }
        }
        return total;
    }
}

